export interface QrStyleState {
  size: number;
  margin: number;
  errorCorrectionLevel: ErrorCorrectionLevel;
  fgColor: string;
  bgColor: string;
  dotsType: DotType;
  cornersSquareType: CornerSquareType;
  cornersDotType: CornerDotType;
  imageDataUrl: string | null;
  imageSize: number;
  hideBackgroundDots: boolean;
}

