import type { FC, MutableRefObject } from 'react';
import { useState } from 'react';
import { Download, Copy, Check } from 'lucide-react';
import { toast } from 'sonner';
import type QRCodeStyling from 'qr-code-styling';

interface ExportBarProps {
  qrRef: MutableRefObject<QRCodeStyling | null>;
  disabled: boolean;
}

const buttonBase =
  'inline-flex items-center justify-center gap-1.5 px-2 py-2.5 rounded-lg text-xs sm:text-sm font-medium text-center transition-colors disabled:opacity-40 disabled:cursor-not-allowed';

const ExportBar: FC<ExportBarProps> = ({ qrRef, disabled }) => {
  const [copied, setCopied] = useState(false);

  const handleDownload = async (extension: 'png' | 'svg') => {
    if (!qrRef.current) return;
    try {
      await qrRef.current.download({ name: 'qr-code', extension });
    } catch {
      toast.error('Download failed');
    }
  };

  const handleCopyImage = async () => {
    if (!qrRef.current) return;
    try {
      const blob = await qrRef.current.getRawData('png');
      if (!(blob instanceof Blob)) throw new Error('No image data');
      await navigator.clipboard.write([new ClipboardItem({ [blob.type]: blob })]);
      setCopied(true);
      toast.success('Copied QR code image');
      window.setTimeout(() => setCopied(false), 1500);
    } catch {
      toast.error('Copy failed — try downloading instead');
    }
  };

  return (
    <div className="grid grid-cols-3 gap-2">
      <button
        type="button"
        disabled={disabled}
        onClick={() => handleDownload('png')}
        className={`${buttonBase} border border-border text-foreground/80 hover:text-foreground hover:border-accent/40`}
      >
        <Download className="w-4 h-4" />
        Download PNG
      </button>
      <button
        type="button"
        disabled={disabled}
        onClick={() => handleDownload('svg')}
        className={`${buttonBase} border border-border text-foreground/80 hover:text-foreground hover:border-accent/40`}
      >
        <Download className="w-4 h-4" />
        Download SVG
      </button>
      <button
        type="button"
        disabled={disabled}
        onClick={handleCopyImage}
        className={`${buttonBase} border border-border text-foreground/80 hover:text-foreground hover:border-accent/40`}
      >
        {copied ? <Check className="w-4 h-4 text-accent" /> : <Copy className="w-4 h-4" />}
        Copy Image
      </button>
    </div>
  );
};

export default ExportBar;
