import type { FC, MutableRefObject } from 'react';
import { useEffect, useRef } from 'react';
import QRCodeStyling from 'qr-code-styling';
import { QrCode } from 'lucide-react';
import type { QrStyleState } from '@/lib/qr/style';

interface QrPreviewProps {
  data: string;
  style: QrStyleState;
  qrRef: MutableRefObject<QRCodeStyling | null>;
}

// Owns the qr-code-styling instance: creates it once content exists, calls
// .update() on subsequent changes, and tears it down when content is cleared
// so the empty-state placeholder shows again. The instance is written to the
// shared qrRef so ExportBar can call .download()/.getRawData() on the same
// object without re-creating it.
const QrPreview: FC<QrPreviewProps> = ({ data, style, qrRef }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const hasContent = data.trim().length > 0;

  useEffect(() => {
    if (!hasContent) {
      qrRef.current = null;
      if (containerRef.current) containerRef.current.innerHTML = '';
      return;
    }

    const options = {
      width: style.size,
      height: style.size,
      type: 'svg' as const,
      data,
      margin: style.margin,
      qrOptions: { errorCorrectionLevel: style.errorCorrectionLevel },
      dotsOptions: { type: style.dotsType, color: style.fgColor },
      cornersSquareOptions: { type: style.cornersSquareType, color: style.fgColor },
      cornersDotOptions: { type: style.cornersDotType, color: style.fgColor },
      backgroundOptions: { color: style.bgColor },
      image: style.imageDataUrl ?? undefined,
      imageOptions: {
        hideBackgroundDots: style.hideBackgroundDots,
        imageSize: style.imageSize,
        margin: 4,
      },
    };

    if (!qrRef.current) {
      qrRef.current = new QRCodeStyling(options);
      if (containerRef.current) {
        containerRef.current.innerHTML = '';
        qrRef.current.append(containerRef.current);
      }
    } else {
      qrRef.current.update(options);
    }
  }, [
    qrRef,
    hasContent,
    data,
    style.size,
    style.margin,
    style.errorCorrectionLevel,
    style.fgColor,
    style.bgColor,
    style.dotsType,
    style.cornersSquareType,
    style.cornersDotType,
    style.imageDataUrl,
    style.imageSize,
    style.hideBackgroundDots,
  ]);

  return (
    <div className="glass-panel hover:border-border aspect-square w-full max-w-[420px] mx-auto flex items-center justify-center p-4">
      {hasContent ? (
        <div
          ref={containerRef}
          className="[&>svg]:max-w-full [&>svg]:h-auto [&>canvas]:max-w-full [&>canvas]:h-auto"
        />
      ) : (
        <div className="flex flex-col items-center gap-3 text-center px-6">
          <QrCode className="w-10 h-10 text-muted-foreground/40" />
          <p className="text-sm text-muted-foreground">Enter content to generate your QR code</p>
        </div>
      )}
    </div>
  );
};

export default QrPreview;
